mapper.select:
select user_id, granted_amount, discarded_amount
from wallet_test_credit_quota
where user_id = #{userId, jdbcType=BINARY}

mapper.update:
update wallet_test_credit_quota
set granted_amount = granted_amount + #{amount},
    update_time = current_timestamp
where user_id = #{userId, jdbcType=BINARY}
  and granted_amount <= #{quota} - #{amount}

update wallet_test_credit_quota
set discarded_amount = discarded_amount + #{amount},
    update_time = current_timestamp
where user_id = #{userId, jdbcType=BINARY}
  and discarded_amount <= #{quota} - #{amount}
  and discarded_amount <= granted_amount - #{amount}
